create table visitor_category(id uuid primary key,created_at timestamptz,updated_at timestamptz,version bigint,deleted boolean not null,code varchar(50) unique,name_en varchar(100),name_ar varchar(100),approval_required boolean not null);
create table host(id uuid primary key,created_at timestamptz,updated_at timestamptz,version bigint,deleted boolean not null,employee_id varchar(50) unique,full_name varchar(150),department varchar(100),email varchar(150),phone varchar(50));
create table visit_application(id uuid primary key,created_at timestamptz,updated_at timestamptz,version bigint,deleted boolean not null,application_number varchar(60) unique,full_name varchar(160),category_code varchar(50),document_type varchar(50),masked_document_number varchar(80),company_name varchar(160),host_employee_id varchar(50),visit_purpose varchar(120),location_name varchar(120),gate_name varchar(80),valid_from timestamptz,valid_until timestamptz,status varchar(40),photo_path varchar(500),qr_token varchar(160) unique);
create table audit_log(id uuid primary key,created_at timestamptz,updated_at timestamptz,version bigint,deleted boolean not null,actor varchar(100),action varchar(80),entity_type varchar(80),entity_id varchar(80),remarks text);
create table check_in_out_event(id uuid primary key,created_at timestamptz,updated_at timestamptz,version bigint,deleted boolean not null,pass_id uuid,event_type varchar(40),gate_name varchar(80),terminal varchar(80),remarks text);
create index idx_visit_status on visit_application(status);create index idx_qr_token on visit_application(qr_token);
